var e={"setup.title":`Te damos la bienvenida a Harness Maxxing`,"setup.subtitle":`Elige la contraseña que protege esta sala de control.`,"setup.token":`Token de instalación`,"setup.tokenHint":"Lo muestra el instalador. Ejecuta `maxxing setup-link` en el servidor para verlo de nuevo.","setup.tokenRequired":`El token de instalación es obligatorio.`,"setup.badToken":"Este enlace de instalación no es válido, ha caducado (dura 1 hora) o ya se ha usado. Ejecuta `maxxing setup-link` en el servidor para obtener uno nuevo.","setup.newLink":`Genera un nuevo enlace en el servidor:`,"setup.submit":`Crear contraseña`,"setup.footer":`Solo tú puedes completar este paso: requiere el token de un solo uso.`,"login.title":`Iniciar sesión`,"login.subtitle":`Introduce tu contraseña de Harness Maxxing.`,"login.password":`Contraseña`,"login.required":`Introduce tu contraseña.`,"login.bad":`Contraseña incorrecta.`,"login.throttled":`Demasiados intentos. Espera un poco antes de volver a intentarlo.`,"login.submit":`Iniciar sesión`,"login.forgot":`¿Olvidaste tu contraseña?`,"login.forgotHelp":`Restablécela desde un terminal en el servidor:`,"pw.new":`Nueva contraseña`,"pw.confirm":`Confirmar contraseña`,"pw.hint":`Al menos 12 caracteres. Lo mejor es una frase de contraseña larga.`,"pw.tooShort":`Usa al menos 12 caracteres.`,"pw.mismatch":`Las contraseñas no coinciden.`,"pw.strength.0":`Vacía`,"pw.strength.1":`Demasiado débil`,"pw.strength.2":`Regular`,"pw.strength.3":`Buena`,"pw.strength.4":`Sólida`,"onb.title":`Primeros pasos`,"onb.progress":`Progreso de la configuración`,"onb.stepOf":`Paso {n} de {total}`,"onb.optional":`Opcional`,"onb.skip":`Omitir por ahora`,"onb.step.language":`Idioma y zona horaria`,"onb.step.claude":`Conectar Claude`,"onb.step.workspace":`Tus proyectos`,"onb.step.telegram":`Telegram`,"onb.step.backup":`Copia de seguridad de la memoria`,"onb.step.done":`Listo`,"onb.language.title":`Idioma y zona horaria`,"onb.language.desc":`Se usan para la interfaz, las fechas y la programación de tus tareas programadas.`,"onb.claude.title":`Conectar Claude`,"onb.claude.desc":`Harness Maxxing controla la CLI oficial de Claude Code en este servidor, con tu propia cuenta o clave de API. No se comparte nada con nadie más.`,"onb.claude.defaults":`Valores predeterminados`,"onb.claude.defaultsDesc":`Modelo y permisos que usarán las nuevas sesiones. Podrás cambiarlos después en cada sesión.`,"onb.claude.later":`Conectar más tarde`,"onb.workspace.title":`Elige tus proyectos iniciales`,"onb.workspace.desc":`Proyectos listos para usar según tu tipo de trabajo: sus temas ya conocen el oficio y te hacen algunas preguntas. Instálalos todos, elige o sáltate este paso: podrás añadirlos más tarde en Ajustes -> Plantillas.`,"onb.workspace.created":`Proyecto y tema creados`,"onb.telegram.title":`Habla con Harness desde Telegram`,"onb.telegram.desc":`Tu propio bot, un hilo por cada sesión abierta: las mismas conversaciones que en el navegador, en tu móvil. Escribe en el chat principal para iniciar una nueva. Los informes de tareas programadas y las alertas de inicio de sesión también llegan ahí.`,"onb.backup.title":`Haz una copia de seguridad de tu memoria`,"onb.backup.desc":`Cada noche, tus CLAUDE.md, archivos de memoria, tareas y tareas programadas se envían a un repositorio privado de GitHub.`,"onb.done.title":`Todo está listo`,"onb.done.desc":`Esto es lo que está configurado. Todo se puede cambiar más tarde en Ajustes.`,"onb.done.finish":`Abrir sesiones`,"onb.summary.password":`Contraseña`,"onb.summary.claude":`Conexión con Claude`,"onb.summary.workspace":`Primer proyecto`,"onb.summary.telegram":`Telegram`,"onb.summary.backup":`Copia de seguridad de la memoria`,"onb.summary.skipped":`omitido`,"onb.summary.todo":`pendiente`,"onb.tour.sessions":`Muchas conversaciones persistentes por tema, en directo, con modelo y coste.`,"onb.tour.files":`Explora, previsualiza y edita cualquier archivo del espacio de trabajo.`,"onb.tour.tasks":`Un kanban que Harness también puede leer y actualizar.`,"onb.tour.crons":`Programa comandos de shell o prompts de Harness, con informes.`,"onb.tour.telegram":`Continúa cualquier conversación desde tu móvil.`,"onb.tour.docs":`Guías, solución de problemas y cómo escribir extensiones.`,"onb.tour.features":`Páginas opcionales que puedes activar cuando las necesites: Tareas, Agentes, Correo, Git, Infra, Equipo.`,"onb.step.profile":`Sobre ti`,"onb.profile.title":`Preséntate (opcional)`,"onb.profile.desc":`Harness Maxxing es gratuito y no necesita ninguna cuenta. Aun así, puedes contarnos quién eres: todo en esta página es opcional.`,"onb.profile.pseudoDesc":`Tu seudónimo en Harness Maxxing (en las copias de tus mensajes en Telegram). Se puede cambiar en Ajustes → Perfil.`,"onb.profile.counterOn":`Se envía a api.harness-maxxing.com. Tu seudónimo y tu idioma solo se envían junto con un correo electrónico. Un contador anónimo (versión, sistema, códigos de estado; sin nombre ni IP) está activado por defecto: puedes desactivarlo en Ajustes → Perfil.`,"twofa.title":`Aprueba en Telegram`,"twofa.subtitle":`La verificación en dos pasos está activada: este navegador necesita tu aprobación.`,"twofa.check":`Revisa Telegram`,"twofa.checkDesc":`Se envió una solicitud de inicio de sesión al hilo Alertas de tu bot. Pulsa Permitir o escribe el código del mensaje de abajo.`,"twofa.waiting":`Esperando tu aprobación… {time}`,"twofa.code":`Código del mensaje`,"twofa.codeLength":`El código tiene 6 dígitos.`,"twofa.badCode":`Código incorrecto.`,"twofa.codesPaused":`Demasiados códigos incorrectos en este servidor: usa el botón Permitir en Telegram o vuelve a probar un código dentro de una hora`,"twofa.verify":`Verificar`,"twofa.trust":`Confiar en este navegador durante 30 días`,"twofa.denied":`Inicio de sesión denegado en Telegram.`,"twofa.expired":`La solicitud ha caducado: vuelve a iniciar sesión.`,"twofa.noAnswer":`¿Telegram no responde?`,"twofa.noAnswerHelp":`Desactiva la verificación en dos pasos desde un terminal en el servidor y luego inicia sesión con la contraseña:`,"twofa.setting":`Verificación en dos pasos`,"twofa.settingDesc":`Tras la contraseña, un navegador nuevo espera tu aprobación en Telegram (botón Permitir o código). Salida sin la interfaz: maxxing 2fa off en el servidor.`,"twofa.forget":`Olvidar los navegadores de confianza`,"twofa.forgotten":`Todos los demás navegadores volverán a pedirlo.`,"twofa.enableTitle":`Activar la verificación en dos pasos`,"twofa.enableDesc":`Aprueba la solicitud enviada a Telegram: así se comprueba que el bot responde antes de que proteja tu inicio de sesión.`,"twofa.offTitle":`Desactivar la verificación en dos pasos`,"twofa.offDesc":`Escribe tu contraseña actual: Telegram recibirá un aviso.`,"twofa.offConfirm":`Desactivar`,"twofa.enabled":`La verificación en dos pasos está activada.`,"twofa.needTelegram":`La verificación en dos pasos pide tu aprobación en Telegram después de la contraseña: primero vincula un bot de Telegram.`,"twofa.linkTelegram":`Ajustes -> Telegram`,"twofa.appCode":`Código de tu aplicación de autenticación`,"twofa.appHint":`También sirve un código de tu aplicación de autenticación o un código de recuperación.`,"twofa.recHint":`También sirve un código de recuperación.`,"twofa.noCode":`¿No tienes un código a mano?`,"onb.workspace.own":`O crea tu propio proyecto`,"onb.step.import":`Importar`,"onb.import.title":`¿Vienes de otro agente?`,"onb.import.desc":`Recupera todo lo que sabe tu agente actual (proyectos, temas, memoria, skills) en dos minutos. O sáltate este paso y empieza desde cero.`,"onb.import.skip":`Empezar desde cero`,"onb.step.features":`Tus páginas`,"onb.features.title":`¿Qué vas a usar?`,"onb.features.desc":`Sesiones, Archivos y Notificaciones siempre están ahí. Activa las demás páginas que necesites ahora: puedes cambiarlo en cualquier momento en Ajustes -> Funciones.`,"onb.done.notify":`Avisarme cuando termine una sesión`,"onb.done.notifyDesc":`Una notificación del navegador cuando Claude termina y esta pestaña no está al frente.`};export{e as default};